import { AdapterRegistry } from "../core/AdapterRegistry.mjs";
import { StatusEffectCatalog } from "./StatusEffectCatalog.mjs";

/**
 * Finds the ActiveEffect on an actor that represents a status id. An effect matches when its
 * statuses set contains the id, its slug equals the id, or its core statusId flag equals the id.
 * @module conditions/StatusEffectMatcher
 */
export class StatusEffectMatcher {
  /**
   * Applied plus temporary effects of an actor
   * @param {Actor} actor
   * @returns {ActiveEffect[]}
   */
  static getAllEffects(actor) {
    if (!actor) return [];
    return [...(actor.appliedEffects ?? []), ...(actor.temporaryEffects ?? [])];
  }

  /**
   * Whether an effect represents a status id
   * @param {ActiveEffect} effect
   * @param {string} statusId
   * @returns {boolean}
   */
  static matches(effect, statusId) {
    return !!effect && (
      effect.statuses?.has?.(statusId)
      || effect.slug === statusId
      || effect.flags?.core?.statusId === statusId
    );
  }

  /**
   * The effect on the actor representing the status id
   * @param {Actor} actor
   * @param {string} statusId
   * @returns {ActiveEffect|null}
   */
  static findEffect(actor, statusId) {
    if (!statusId) return null;
    return this.getAllEffects(actor).find(effect => this.matches(effect, statusId)) ?? null;
  }

  /**
   * Whether the actor has the status. Delegates to the adapter's conditions.has when defined.
   * @param {Actor} actor
   * @param {string} statusId
   * @returns {boolean}
   */
  static hasEffect(actor, statusId) {
    if (!actor || !statusId) return false;
    const adapterHas = AdapterRegistry.active.conditions?.has;
    if (typeof adapterHas === "function") {
      const statusEffect = StatusEffectCatalog.getStatusEffect(statusId) ?? { id: statusId };
      return !!adapterHas(statusEffect, actor);
    }
    return !!this.findEffect(actor, statusId);
  }
}
