/**
 * Capability names a SystemAdapter can provide. The UI, settings and actions only expose
 * features whose capability is present on the active adapter; everything else is Tier 0
 * behaviour that works in any system.
 * @module core/Capabilities
 */

export const CAPABILITIES = {
  STATS: "stats",
  ROLLS: "rolls",
  GROUPS: "groups",
  CONDITIONS: "conditions",
  ACTOR_TYPES: "actorTypes",
  HOOKS: "hooks"
};

/**
 * @typedef {Object} StatDef
 * @property {string} abbrev - Short label shown in the bar (e.g. "HP")
 * @property {string} path - Property path on the actor or a formula of paths (e.g. "system.attributes.ac.value")
 * @property {string} [icon] - Font Awesome class shown instead of the abbreviation
 * @property {string} [maxPath] - Path to a maximum value, shown as value/max
 * @property {boolean} [usageTracking] - The value counts consumption, not remaining amount
 */

/**
 * @typedef {Object} ResourceDef
 * @property {string} id - Unique id used by the "tracked resource" setting
 * @property {string} label - Display label
 * @property {string} currentValuePath - Path to the current value
 * @property {string} maxValuePath - Path to the maximum value
 * @property {boolean} [usageTracking] - The value counts consumption, not remaining amount
 */

/**
 * @typedef {Object} RollTypeDef
 * @property {string} type - Roll type identifier passed back to roll()
 * @property {string} label - Display label
 * @property {boolean} [nested] - Whether the type expands into options
 * @property {Array<{key: string, label: string}>} [options] - Nested options
 */

/**
 * @typedef {Object} SuccessResult
 * @property {boolean|string} passed - true/false, or a degree string such as "critical-success"
 * @property {string[]} [properties] - Extra properties such as ["critical"]
 */

/**
 * @typedef {Object} AdapterRollResult
 * @property {Roll} [roll] - The evaluated Roll
 * @property {number} [total] - Roll total
 * @property {string} [formula] - Roll formula
 * @property {SuccessResult|null} [success] - Success evaluation against a target
 * @property {boolean} [cancelled] - The user cancelled the roll
 * @property {boolean} [error] - The roll failed
 * @property {string} [message] - Error message
 */

/**
 * @typedef {Object} RollsSection
 * @property {string} [icon] - Font Awesome class for roll entries (default fa-dice-d20)
 * @property {function(Actor[]): RollTypeDef[]} getRollTypes - Roll types available for the given actors
 * @property {function(Actor, string, Object): Promise<AdapterRollResult>} roll - Execute a roll
 * @property {function(Actor, string, string): number} [getValue] - Modifier for a roll type/key
 * @property {function(Roll, number, Actor, Object): SuccessResult} [rollSuccess] - Evaluate success against a target
 * @property {function(Object, number): (SuccessResult|null)} [gradeResult] - Evaluate a normalised result ({total, dice}) against
 *   a target set after the roll, for example a DC typed on the group roll card. Without it the total is compared with the target.
 * @property {function(SuccessResult): string} [formatSuccess] - Display text for a success result
 * @property {function(string): boolean} [supportsTarget] - Whether a roll type accepts a target number
 * @property {boolean} [totalIsSuccessCount] - Totals are a count of successes, so one success passes when no target applies
 * @property {Array<{id: number, label: string}>} [groupRollModes] - Extra or replacement group roll modes
 * @property {number} [defaultGroupRollMode] - Default group roll mode id
 * @property {function(Array, string, Object, number): (Object|null)} [calculateGroupRollBonus] - Pre-roll bonus per participant
 * @property {function(Array, string, Object, number): (GroupRollPlan|null)} [planGroupRoll] - Nominate one participant to roll for the group; the others are marked as helping and do not roll
 * @property {function(number, Map, (number|null), (string|null)): (Object|null)} [calculateGroupResult] - Group result for an adapter mode
 * @property {boolean} [hasCritical]
 * @property {boolean} [useDegrees]
 */

/**
 * @typedef {Object} GroupsSection
 * @property {function(Actor): boolean} isGroupActor
 * @property {function(): Actor[]} getGroupActors
 * @property {function(Actor): Promise<Array<{actor: Actor, quantity: number}>>} getGroupMembers
 * @property {function(string, string, Actor[]): Promise<Actor|null|undefined>} [createGroup] - Create a group actor of a type with members; return undefined to fall back to the core
 * @property {function(Actor, Actor): Promise<boolean|undefined>} [removeGroupMember] - Remove a member from a group actor; return undefined to fall back to the core
 * @property {string[]} [renderHooks] - Hooks fired when a group sheet renders
 */

/**
 * @typedef {Object} ConditionsSection
 * @property {function(): Array} [getStatusEffects] - Replacement catalogue of status effects
 * @property {function(Object, Actor): Promise<boolean>} [apply]
 * @property {function(Object, Actor): Promise<boolean>} [remove]
 * @property {function(Object, Actor): boolean} [has]
 */

/**
 * @typedef {Object} ActorTypesSection
 * @property {string[]|null} [listed] - Actor types shown in the bar; null lists every type
 * @property {string[]} [group] - Actor types treated as groups
 */

/**
 * @typedef {Object} StatsSection
 * @property {StatDef[]|function(Actor): StatDef[]} [list]
 * @property {ResourceDef[]|function(Actor): ResourceDef[]} [resources]
 */
