import { HOOKS_CORE } from "../constants/Hooks.mjs";
import { getSettings } from "../constants/Settings.mjs";
import { SettingsUtil } from "../utils/SettingsUtil.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";

/**
 * Hooks published by Dice So Nice for the lifetime of a 3D roll animation
 */
const DSN_HOOKS = {
  START: "diceSoNiceRollStart",
  COMPLETE: "diceSoNiceRollComplete"
};

/**
 * Time given to Dice So Nice to pick up a freshly created message before the pacer decides
 * nothing is being animated
 */
const START_GRACE_MS = 250;

/**
 * Upper bound for a single animation. Comfortably longer than a Dice So Nice roll but short
 * enough that a completion hook lost to a deleted message cannot stall a batch
 */
const MAX_WAIT_MS = 4000;

/**
 * Poll interval used while waiting for animations to finish
 */
const POLL_MS = 50;

/**
 * Spaces out the rolls of a multi-actor action. Without it every roll of a batch resolves as soon
 * as its chat message exists, so with roll dialogs skipped the whole group lands at once and
 * Dice So Nice animates all of them together. While a batch runs the pacer records the messages
 * it creates and waits for their 3D animation to finish before the next roll starts, falling back
 * to a fixed delay when nothing is animated.
 * @module rolls/RollPacer
 */
export class RollPacer {
  /** @type {Set<string>} */
  static #messageIds = new Set();

  /** @type {Set<string>} */
  static #started = new Set();

  /** @type {Set<string>} */
  static #completed = new Set();

  /** @type {{create: number, start: number, complete: number}|null} */
  static #hookIds = null;

  /**
   * Fallback delay in milliseconds, also the master switch: 0 disables pacing entirely
   * @returns {number}
   */
  static get delay() {
    return Number(SettingsUtil.get(getSettings().rollPacingDelay.tag)) || 0;
  }

  /**
   * Whether rolls of a batch should be paced at all
   * @returns {boolean}
   */
  static get enabled() {
    return this.delay > 0;
  }

  /**
   * Whether Dice So Nice is available to animate rolls on this client
   * @returns {boolean}
   */
  static get dsnActive() {
    return !!game.dice3d && game.modules.get("dice-so-nice")?.active === true;
  }

  /**
   * Start watching the messages and animations produced by a batch
   */
  static begin() {
    if (!this.enabled || this.#hookIds) return;
    this.#hookIds = {
      create: Hooks.on(HOOKS_CORE.CREATE_CHAT_MESSAGE, message => this.#onMessage(message)),
      start: Hooks.on(DSN_HOOKS.START, id => this.#record(this.#started, id)),
      complete: Hooks.on(DSN_HOOKS.COMPLETE, id => this.#record(this.#completed, id))
    };
    this.reset();
  }

  /**
   * Stop watching and forget everything recorded for the batch
   */
  static end() {
    if (!this.#hookIds) return;
    Hooks.off(HOOKS_CORE.CREATE_CHAT_MESSAGE, this.#hookIds.create);
    Hooks.off(DSN_HOOKS.START, this.#hookIds.start);
    Hooks.off(DSN_HOOKS.COMPLETE, this.#hookIds.complete);
    this.#hookIds = null;
    this.reset();
  }

  /**
   * Drop the messages and animations recorded so far
   */
  static reset() {
    this.#messageIds.clear();
    this.#started.clear();
    this.#completed.clear();
  }

  /**
   * Wait until the roll that just finished has stopped animating, then clear the window so the
   * next roll starts from a clean slate. Returns immediately when pacing is off.
   * @returns {Promise<void>}
   */
  static async settle() {
    if (!this.enabled || !this.#hookIds) return;
    const animated = this.dsnActive ? await this.#waitForAnimations() : false;
    this.reset();
    if (animated) return;
    await this.#sleep(this.delay);
  }

  /**
   * Wait for every animation started for this window to complete
   * @returns {Promise<boolean>} Whether anything was actually animated
   */
  static async #waitForAnimations() {
    await this.#sleep(START_GRACE_MS);
    if (!this.#startedHere().length) return false;
    const deadline = Date.now() + MAX_WAIT_MS;
    while (this.#pending().length && Date.now() < deadline) {
      await this.#sleep(POLL_MS);
    }
    if (this.#pending().length) {
      LogUtil.log("RollPacer.#waitForAnimations - timed out", [this.#pending()]);
    }
    return true;
  }

  /**
   * Messages of this window whose animation started but has not completed
   * @returns {string[]}
   */
  static #pending() {
    return this.#startedHere().filter(id => !this.#completed.has(id));
  }

  /**
   * Messages of this window Dice So Nice started animating
   * @returns {string[]}
   */
  static #startedHere() {
    return [...this.#messageIds].filter(id => this.#started.has(id));
  }

  /**
   * Record a chat message created while the batch runs
   * @param {ChatMessage} message
   */
  static #onMessage(message) {
    const authorId = message?.author?.id ?? message?.user?.id ?? null;
    if (!message?.id || (authorId && authorId !== game.user.id)) return;
    this.#messageIds.add(message.id);
  }

  /**
   * Record a Dice So Nice message id
   * @param {Set<string>} set
   * @param {string} id
   */
  static #record(set, id) {
    if (typeof id === "string" && id) set.add(id);
  }

  /**
   * Resolve after the given number of milliseconds
   * @param {number} ms
   * @returns {Promise<void>}
   */
  static #sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}
