import { LANG_PREFIX } from "../../constants/General.mjs";
import { AdapterRegistry } from "../../core/AdapterRegistry.mjs";
import { GenericGroups } from "../../adapters/generic/GenericGroups.mjs";
import { SavedGroups } from "./SavedGroups.mjs";
import { NotifyUtil } from "../../utils/NotifyUtil.mjs";
import { LogUtil } from "../../utils/LogUtil.mjs";

/**
 * @typedef {Object} MemberRef
 * @property {string} groupId - Saved group id or group actor id
 * @property {"saved"|"adapter"} source - Where the group comes from
 * @property {string} groupName
 * @property {string} actorId - Member's actor id
 * @property {string|null} [tokenId] - Member's token id, for unlinked members
 * @property {string} memberName
 */

/**
 * Removes members from groups shown in the token bar. Saved groups edit their stored list (offering to delete
 * a group left empty); system group actors are changed only after confirmation, through the adapter's
 * removeGroupMember when it has one, otherwise through GenericGroups.
 * @module actors/groups/GroupMembership
 */
export class GroupMembership {
  /**
   * Member reference for an actor card shown inside a group, or null when the card is not in a group
   * @param {HTMLElement} actorElement - The member's `.actor` element
   * @returns {MemberRef|null}
   */
  static memberRefFrom(actorElement) {
    const groupRow = actorElement?.closest("li.group-row");
    const groupElement = groupRow?.querySelector(":scope > .actor-group");
    if (!groupElement || !actorElement.closest(".group-members")) return null;
    return {
      groupId: groupElement.dataset.id,
      source: groupElement.dataset.source === "saved" ? "saved" : "adapter",
      groupName: groupElement.querySelector(".actor-name")?.textContent?.trim() ?? "",
      actorId: actorElement.dataset.actorId,
      tokenId: actorElement.dataset.tokenId || null,
      memberName: actorElement.querySelector(".actor-name")?.textContent?.trim() ?? ""
    };
  }

  /**
   * Remove a member from its group
   * @param {MemberRef} ref
   * @returns {Promise<boolean>} Whether the member was removed
   */
  static async remove(ref) {
    if (!game.user.isGM || !ref?.groupId || !ref.actorId) return false;
    try {
      const removed = ref.source === "saved" ? await this.#removeFromSaved(ref) : await this.#removeFromActor(ref);
      if (removed) NotifyUtil.info(game.i18n.format(`${LANG_PREFIX}.notifications.memberRemoved`, { member: ref.memberName, group: ref.groupName }));
      return removed;
    } catch (error) {
      LogUtil.error("GroupMembership.remove", [error, ref]);
      NotifyUtil.error(game.i18n.format(`${LANG_PREFIX}.notifications.memberRemoveFailed`, { member: ref.memberName, group: ref.groupName }));
      return false;
    }
  }

  /**
   * Remove from a saved group; when it ends up empty, offer to delete it
   * @param {MemberRef} ref
   * @returns {Promise<boolean>}
   */
  static async #removeFromSaved(ref) {
    const left = await SavedGroups.removeMember(ref.groupId, { actorId: ref.actorId, tokenId: ref.tokenId });
    if (left < 0) return false;
    if (left === 0 && await this.#confirm("deleteEmptyTitle", "deleteEmptyConfirm", ref)) {
      await SavedGroups.remove(ref.groupId);
    }
    return true;
  }

  /**
   * Remove from a system group actor after confirmation
   * @param {MemberRef} ref
   * @returns {Promise<boolean>}
   */
  static async #removeFromActor(ref) {
    const groupActor = game.actors.get(ref.groupId);
    const memberActor = game.actors.get(ref.actorId);
    if (!groupActor || !memberActor) return false;
    if (!await this.#confirm("removeMemberTitle", "removeMemberConfirm", ref)) return false;
    const adapterGroups = AdapterRegistry.active.groups;
    if (typeof adapterGroups?.removeGroupMember === "function" && adapterGroups.isGroupActor?.(groupActor)) {
      const handled = await adapterGroups.removeGroupMember(groupActor, memberActor);
      if (handled !== undefined) return !!handled;
    }
    return GenericGroups.removeMember(groupActor, memberActor);
  }

  /**
   * Yes/no dialog
   * @param {string} titleKey - Key under ui.groups
   * @param {string} contentKey - Key under ui.groups, formatted with member and group names
   * @param {MemberRef} ref
   * @returns {Promise<boolean>}
   */
  static async #confirm(titleKey, contentKey, ref) {
    const confirmed = await foundry.applications.api.DialogV2.confirm({
      window: { title: game.i18n.localize(`${LANG_PREFIX}.ui.groups.${titleKey}`) },
      content: `<p>${game.i18n.format(`${LANG_PREFIX}.ui.groups.${contentKey}`, { member: ref.memberName, group: ref.groupName })}</p>`,
      rejectClose: false
    });
    return !!confirmed;
  }
}
