import { MODULE_ID, LANG_PREFIX } from "../constants/General.mjs";
import { HOOKS_SOCKET } from "../constants/Hooks.mjs";
import { LogUtil } from "./LogUtil.mjs";

/**
 * Thin wrapper around socketlib for GM/player communication
 * @module utils/SocketUtil
 */
export class SocketUtil {
  /** @type {Object|null} socketlib socket */
  static socket = null;

  /**
   * Register the module with socketlib once it is ready
   * @param {Function} [callbackFunc] - Called after registration so handlers can be registered
   */
  static initialize(callbackFunc) {
    Hooks.once(HOOKS_SOCKET.READY, () => {
      if (typeof socketlib === "undefined") {
        LogUtil.error("socketlib is not loaded. Roll requests are disabled.");
        ui.notifications?.error(game.i18n.localize(`${LANG_PREFIX}.notifications.socketlibMissing`), { permanent: true });
        return;
      }
      try {
        SocketUtil.socket = socketlib.registerModule(MODULE_ID);
        callbackFunc?.();
      } catch (e) {
        LogUtil.error("SocketUtil.initialize failed", [e]);
      }
    });
  }

  /**
   * Whether the socket is available
   * @returns {boolean}
   */
  static get ready() {
    return !!SocketUtil.socket;
  }

  /**
   * Register a remotely callable function
   * @param {string} name
   * @param {Function} func
   */
  static registerCall(name, func) {
    if (!SocketUtil.socket) {
      LogUtil.warn("SocketUtil.registerCall - socket not ready", [name]);
      return;
    }
    SocketUtil.socket.register(name, func);
  }

  /**
   * Execute a registered call on every connected GM
   * @param {string} handler
   * @param {...*} parameters
   * @returns {Promise<*>}
   */
  static async execForGMs(handler, ...parameters) {
    if (!SocketUtil.socket) return null;
    return SocketUtil.socket.executeForAllGMs(handler, ...parameters);
  }

  /**
   * Execute a registered call on every connected client
   * @param {string} handler
   * @param {...*} parameters
   * @returns {Promise<*>}
   */
  static async execForAll(handler, ...parameters) {
    if (!SocketUtil.socket) return null;
    return SocketUtil.socket.executeForEveryone(handler, ...parameters);
  }

  /**
   * Execute a registered call as a specific user
   * @param {string} handler
   * @param {string} userId
   * @param {...*} parameters
   * @returns {Promise<*>}
   */
  static async execForUser(handler, userId, ...parameters) {
    if (!SocketUtil.socket) return null;
    if (userId === game.user.id) return null;
    try {
      return await SocketUtil.socket.executeAsUser(handler, userId, ...parameters);
    } catch (error) {
      LogUtil.error("SocketUtil.execForUser failed", [handler, userId, error]);
      return null;
    }
  }
}
