import { LANG_PREFIX, TABS } from "../../constants/General.mjs";
import { LogUtil } from "../../utils/LogUtil.mjs";
import { ActorClassifier } from "../ActorClassifier.mjs";
import { ActorStatusFlags } from "../ActorStatusFlags.mjs";
import { NotifyUtil } from "../../utils/NotifyUtil.mjs";

/**
 * Dropping an actor from the directory onto the token bar marks it as a favourite so it is
 * always listed, and switches the menu to the tab the actor belongs to.
 * @module actors/drag/ActorDropUtil
 */
export class ActorDropUtil {
  /**
   * Only GMs may drop actors into the menu
   * @param {string} selector - Drop target selector
   * @returns {boolean}
   */
  static canDrop(selector) {
    LogUtil.log("ActorDropUtil.canDrop", [selector]);
    return game.user.isGM;
  }

  /**
   * Highlight the drop zone while dragging over it
   * @param {DragEvent} event
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   * @returns {boolean}
   */
  static handleDragOver(event, menu) {
    LogUtil.log("ActorDropUtil.handleDragOver", [event.currentTarget, event.target]);
    event.preventDefault();
    event.stopPropagation();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = "copy";
    }
    const dropZone = event.currentTarget?.closest?.(".actor-list, .actors");
    dropZone?.classList.add("drag-over");
    return false;
  }

  /**
   * Remove the highlight when the pointer leaves the drop zone. Called without a usable
   * currentTarget (global dragend) it clears every highlight on the page.
   * @param {DragEvent} event
   */
  static handleDragLeave(event) {
    LogUtil.log("ActorDropUtil.handleDragLeave", [event.currentTarget, event.target]);
    const target = event.currentTarget;
    if (!target || typeof target.getBoundingClientRect !== "function") {
      document.querySelectorAll(".drag-over").forEach(element => element.classList.remove("drag-over"));
      return;
    }
    const rect = target.getBoundingClientRect();
    const isActuallyLeaving = event.clientX < rect.left
      || event.clientX > rect.right
      || event.clientY < rect.top
      || event.clientY > rect.bottom;
    if (isActuallyLeaving) {
      target.closest(".actor-list, .actors")?.classList.remove("drag-over");
    }
  }

  /**
   * Add the dropped actor to the menu
   * @param {DragEvent} event
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static async handleDrop(event, menu) {
    event.preventDefault();
    event.stopPropagation();
    for (const type of event.dataTransfer.types) {
      LogUtil.log(`ActorDropUtil.handleDrop - ${type}:`, [event.dataTransfer.getData(type)]);
    }
    menu.element.querySelectorAll(".drag-over").forEach(element => element.classList.remove("drag-over"));
    try {
      const dragData = this.parseDragData(event);
      if (!dragData || dragData.type !== "Actor") {
        LogUtil.log("ActorDropUtil.handleDrop - Invalid drag data", [dragData]);
        return;
      }
      const actor = await this.getActorFromDragData(dragData);
      if (!actor) {
        NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.actorNotFound`));
        return;
      }
      const targetTab = ActorClassifier.isPlayerOwned(actor) ? TABS.PC : TABS.NPC;
      if (menu.currentTab !== targetTab) {
        menu.currentTab = targetTab;
      }
      await this.addActorToMenu(actor, menu);
    } catch (error) {
      LogUtil.error("ActorDropUtil.handleDrop - Error processing drop", [error]);
      NotifyUtil.error(game.i18n.localize(`${LANG_PREFIX}.notifications.dropError`));
    }
  }

  /**
   * Read the Foundry drag payload from the event
   * @param {DragEvent} event
   * @returns {Object|null}
   */
  static parseDragData(event) {
    try {
      const jsonData = event.dataTransfer.getData("application/json");
      if (jsonData) {
        return JSON.parse(jsonData);
      }
      const textData = event.dataTransfer.getData("text/plain");
      if (!textData) return null;
      if (textData.startsWith("Actor.")) {
        return { type: "Actor", uuid: textData };
      }
      try {
        return JSON.parse(textData);
      } catch (parseError) {
        LogUtil.log("ActorDropUtil.parseDragData - Text is not JSON");
        return null;
      }
    } catch (error) {
      LogUtil.error("ActorDropUtil.parseDragData - Error parsing drag data", [error]);
      return null;
    }
  }

  /**
   * Resolve the dragged actor document
   * @param {Object} dragData
   * @returns {Promise<Actor|null>}
   */
  static async getActorFromDragData(dragData) {
    try {
      if (dragData.uuid) {
        return await fromUuid(dragData.uuid);
      }
      if (dragData.id) {
        return game.actors.get(dragData.id) ?? null;
      }
      return null;
    } catch (error) {
      LogUtil.error("ActorDropUtil.getActorFromDragData - Error getting actor", [error]);
      return null;
    }
  }

  /**
   * Favourite the actor unless it is already listed
   * @param {Actor} actor
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static async addActorToMenu(actor, menu) {
    const { isFavorite, isBlocked } = ActorStatusFlags.getActorStatus(actor);
    if (isFavorite && !isBlocked) {
      NotifyUtil.info(game.i18n.format(`${LANG_PREFIX}.notifications.actorAlreadyAdded`, { actor: actor.name }));
      return;
    }
    await ActorStatusFlags.setFavorite(actor, true);
  }
}
