import { SystemAdapter } from "../SystemAdapter.mjs";
import { CAPABILITIES } from "../../core/Capabilities.mjs";
import { BarAttributeStats } from "./BarAttributeStats.mjs";

/**
 * Adapter used when no system-specific adapter is registered.
 * Stats and resources come from the token bar attributes every system configures,
 * so the bar shows a resource bar plus heal/kill without knowing the data model.
 * @module adapters/generic/GenericAdapter
 */
export class GenericAdapter extends SystemAdapter {
  /**
   * @param {string} systemId - Running system id
   */
  constructor(systemId) {
    super({
      id: systemId,
      name: game.system?.title ?? systemId,
      stats: {
        list: actor => BarAttributeStats.getStatsList(actor),
        resources: actor => BarAttributeStats.getResources(actor)
      }
    });
  }

  /**
   * The generic adapter provides nothing beyond Tier 0, except rolls the GM set up in System Config
   * @returns {string[]}
   */
  get capabilities() {
    return this.rolls ? [CAPABILITIES.ROLLS] : [];
  }
}
