/**
 * Localize a settings label or hint
 * @param {string} key - Setting key
 * @param {string} field - "label" or "hint"
 * @returns {string}
 */
const l = (key, field) => game.i18n.localize(`${LANG_PREFIX}.settings.${key}.${field}`);

