/**
 * Settings shown on a given settings menu tab
 * @param {string} tab - One of SETTING_TABS
 * @returns {Object} Subset of getSettings() keyed by setting key
 */
export function getSettingsForTab(tab) {
  const all = getSettings();
  return Object.fromEntries(Object.entries(all).filter(([, setting]) => setting.tab === tab));
}
