/**
 * @typedef {Object} RollCallContext
 * @property {Actor} actor
 * @property {string} label - Roll label, e.g. "Attributes: Strength"
 * @property {string} [group] - Value group path inside actor.system
 * @property {string} [key] - Chosen option key
 * @property {number|null} [value] - Chosen option's value
 * @property {string} [key2] - Second key of a two-key roll (e.g. the attribute paired with a skill)
 * @property {number|null} [value2] - Value of the second key
 * @property {Item} [item] - Owned item behind the chosen option, for item option sources
 * @property {number|null} [dc] - Target / difficulty
 * @property {string} [rollMode]
 * @property {boolean} [fastForward] - Skip the system's roll dialog
 */

const PLACEHOLDER_PATTERN = /\{(\w+)\}/g;
const WHOLE_PLACEHOLDER_PATTERN = /^\{(\w+)\}$/;

/**
 * @typedef {Object} ParamInfo
 * @property {"object"|"positional"} style - One destructured options object, or positional parameters
 * @property {string[]} names - Parameter names (keys of the options object for the object style)
 */

const ROLE_NAMES = {
  actor: ["actor", "document", "token"],
  data: ["data", "system", "actordata", "rolldata"],
  label: ["title", "label"],
  dc: ["difficulty", "dc", "target", "targetnumber", "tn"],
  rollMode: ["rollmode", "messagemode", "mode"],
  fastForward: ["quickroll", "fastforward", "skipdialog", "skip"],
  path: ["valuepaths", "valuepath", "paths", "path"],
  key: ["key", "id", "stat", "skill", "skillid", "skillname", "skilldata", "attribute", "attributename", "ability", "abilityid", "trait", "characteristic", "characteristicname", "attr"],
  value: ["basicdice", "dice", "pool", "dicepool", "numdice", "number", "value", "count", "rating"]
};

/**
 * Reads a roll function's parameter names from its source and fills the ones it recognises from the roll
 * context: the actor, its data, the label, difficulty, roll mode, dialog skipping, the chosen option's key,
 * path or value. Lets the System Config call a system's own roll methods and API without per-system code.
 * @module adapters/configured/RollCallBuilder
 */
export class RollCallBuilder {
  /**
   * Parameters a function declares
   * @param {Function} fn
   * @returns {ParamInfo}
   */
  static parseParams(fn) {
    const source = typeof fn === "function" ? Function.prototype.toString.call(fn) : "";
    const open = source.indexOf("(");
    if (open === -1) return { style: "positional", names: [] };
    const inner = source.slice(open + 1, this.#matchingClose(source, open)).trim();
    if (inner.startsWith("{")) {
      const objectBody = inner.slice(1, this.#matchingClose(inner, 0));
      return { style: "object", names: this.#topLevelNames(objectBody) };
    }
    return { style: "positional", names: this.#topLevelNames(inner) };
  }

  /**
   * Arguments from an explicit template, as written in a system profile. A string that is exactly one
   * placeholder becomes that value with its type kept ("{fastForward}" -> true); placeholders inside longer
   * strings are interpolated; arrays and objects are filled recursively. Placeholders: {key}, {key2}, {value},
   * {value2}, {path}, {label}, {dc}, {rollMode}, {fastForward}, {actor}, {data}, {item}, {actorId}, {actorUuid}.
   * @param {Array} template
   * @param {RollCallContext} context
   * @returns {Array}
   */
  static fill(template, context) {
    const fillValue = value => {
      if (Array.isArray(value)) return value.map(fillValue);
      if (value && typeof value === "object") {
        return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, fillValue(entry)]).filter(([, entry]) => entry !== undefined));
      }
      if (typeof value !== "string") return value;
      const whole = value.match(WHOLE_PLACEHOLDER_PATTERN);
      if (whole) return this.#placeholder(whole[1], context);
      return value.replace(PLACEHOLDER_PATTERN, (match, name) => {
        const resolved = this.#placeholder(name, context);
        return resolved === undefined || resolved === null ? "" : String(resolved);
      });
    };
    return (Array.isArray(template) ? template : [template]).map(fillValue);
  }

  /**
   * Value of a template placeholder
   * @param {string} name
   * @param {RollCallContext} context
   * @returns {*}
   */
  static #placeholder(name, context) {
    switch (name) {
      case "actor": return context.actor;
      case "actorId": return context.actor?.id;
      case "actorUuid": return context.actor?.uuid;
      case "data": return context.actor?.system;
      case "item": return context.item ?? undefined;
      case "path": return this.#valuePath(context);
      default: return context[name] ?? undefined;
    }
  }

  /**
   * Arguments for a call: one options object, or positional values in declared order
   * @param {Function} fn
   * @param {RollCallContext} context
   * @returns {Array}
   */
  static buildArgs(fn, context) {
    const params = this.parseParams(fn);
    if (params.style === "object") {
      const options = {};
      for (const name of params.names) {
        const value = this.#valueFor(name, context);
        if (value !== undefined) options[name] = value;
      }
      return [options];
    }
    if (params.names.length === 0) return context.key ? [context.key] : [];
    const args = params.names.map(name => this.#valueFor(name, context));
    if (context.key && args[0] === undefined) args[0] = context.key;
    while (args.length && args[args.length - 1] === undefined) args.pop();
    return args;
  }

  /**
   * What a call would fill, as short text for the dialog, e.g. "basicDice ← value · actor · difficulty"
   * @param {Function} fn
   * @returns {string}
   */
  static describe(fn) {
    const params = this.parseParams(fn);
    const filled = params.names
      .map(name => ({ name, role: this.#roleOf(name) }))
      .filter(entry => entry.role)
      .map(entry => ["value", "key", "path"].includes(entry.role) ? `${entry.name} ← ${entry.role}` : entry.name);
    if (params.style === "positional" && params.names.length > 0 && !this.#roleOf(params.names[0])) {
      filled.unshift(`${params.names[0]} ← key`);
    }
    return filled.join(" · ");
  }

  /**
   * How well a function can be called from the roll context: number of recognised parameters,
   * with a bonus when it can receive the chosen option
   * @param {Function} fn
   * @returns {number}
   */
  static score(fn) {
    const roles = this.parseParams(fn).names.map(name => this.#roleOf(name)).filter(Boolean);
    const takesOption = roles.some(role => ["value", "key", "path"].includes(role));
    return roles.length + (takesOption ? 5 : 0);
  }

  /**
   * Context value for a parameter name
   * @param {string} name
   * @param {RollCallContext} context
   * @returns {*}
   */
  static #valueFor(name, context) {
    switch (this.#roleOf(name)) {
      case "actor": return context.actor;
      case "data": return context.actor?.system;
      case "label": return context.label;
      case "dc": return context.dc ?? undefined;
      case "rollMode": return context.rollMode ?? undefined;
      case "fastForward": return context.fastForward ?? undefined;
      case "path": return this.#valuePath(context);
      case "key": return context.key ?? undefined;
      case "value": return context.value ?? undefined;
      default: return undefined;
    }
  }

  /**
   * Role of a parameter name, or null when it is not recognised
   * @param {string} name
   * @returns {string|null}
   */
  static #roleOf(name) {
    const normalized = String(name).toLowerCase().replace(/[^a-z]/g, "");
    for (const [role, names] of Object.entries(ROLE_NAMES)) {
      if (names.includes(normalized)) return role;
    }
    return null;
  }

  /**
   * Path of the chosen option's value relative to actor.system, e.g. "attributes.strength.value"
   * @param {RollCallContext} context
   * @returns {string|undefined}
   */
  static #valuePath(context) {
    if (!context.group || !context.key || context.group.startsWith("@")) return undefined;
    const base = `${context.group}.${context.key}`;
    const entry = foundry.utils.getProperty(context.actor?.system ?? {}, base);
    return entry && typeof entry === "object" && "value" in entry ? `${base}.value` : base;
  }

  /**
   * Names declared at the top level of a parameter list or destructuring pattern, ignoring defaults
   * @param {string} text
   * @returns {string[]}
   */
  static #topLevelNames(text) {
    const names = [];
    let depth = 0;
    let current = "";
    let quote = null;
    for (const char of text) {
      if (quote) {
        if (char === quote) quote = null;
        current += char;
        continue;
      }
      if (char === "'" || char === "\"" || char === "`") quote = char;
      if ("([{".includes(char)) depth++;
      if (")]}".includes(char)) depth--;
      if (char === "," && depth === 0) {
        names.push(current);
        current = "";
        continue;
      }
      current += char;
    }
    names.push(current);
    return names
      .map(part => part.trim().replace(/^\.\.\./, "").split(/[=:]/)[0].trim())
      .filter(name => /^[A-Za-z_$][\w$]*$/.test(name));
  }

  /**
   * Index of the bracket closing the one at `openIndex`, skipping strings
   * @param {string} text
   * @param {number} openIndex
   * @returns {number}
   */
  static #matchingClose(text, openIndex) {
    let depth = 0;
    let quote = null;
    for (let index = openIndex; index < text.length; index++) {
      const char = text[index];
      if (quote) {
        if (char === "\\") index++;
        else if (char === quote) quote = null;
        continue;
      }
      if (char === "'" || char === "\"" || char === "`") quote = char;
      else if ("([{".includes(char)) depth++;
      else if (")]}".includes(char)) {
        depth--;
        if (depth === 0) return index;
      }
    }
    return text.length;
  }
}
