import { MODULE_ID, LANG_PREFIX } from "../constants/General.mjs";
import { getSettings } from "../constants/Settings.mjs";
import { LogUtil } from "./LogUtil.mjs";
import { SettingsUtil } from "./SettingsUtil.mjs";
import { NotifyUtil } from "./NotifyUtil.mjs";

/**
 * Registers prototype wrappers through libWrapper when it is active and degrades gracefully
 * when it is not. Shows a one-time recommendation to GMs when libWrapper is missing.
 * @module utils/LibWrapperUtil
 */
export class LibWrapperUtil {
  static #registeredWrappers = new Set();
  static #libWrapperChecked = false;
  static #libWrapperAvailable = false;

  /**
   * Whether the libWrapper module is active
   * @returns {boolean}
   */
  static isAvailable() {
    if (!this.#libWrapperChecked) {
      this.#libWrapperAvailable = game.modules.get("lib-wrapper")?.active ?? false;
      this.#libWrapperChecked = true;
    }
    return this.#libWrapperAvailable;
  }

  /**
   * Register a wrapper
   * @param {string} target - Path to wrap, e.g. "Token.prototype.animate"
   * @param {Function} fn - Wrapper function
   * @param {string} [type="WRAPPER"] - WRAPPER, MIXED or OVERRIDE
   * @param {Object} [options]
   * @param {boolean} [options.required] - Warn when libWrapper is unavailable
   * @returns {boolean} Whether the wrapper was registered
   */
  static register(target, fn, type = "WRAPPER", options = {}) {
    if (!this.isAvailable()) {
      if (options.required) {
        LogUtil.warn(`LibWrapperUtil.register - libWrapper required but not available for: ${target}`);
      }
      return false;
    }
    try {
      libWrapper.register(MODULE_ID, target, fn, type);
      this.#registeredWrappers.add(target);
      LogUtil.log(`LibWrapperUtil.register - Successfully registered: ${target}`);
      return true;
    } catch (error) {
      LogUtil.error(`LibWrapperUtil.register - Failed to register ${target}:`, [error]);
      return false;
    }
  }

  /**
   * Unregister one wrapper
   * @param {string} target
   */
  static unregister(target) {
    if (!this.isAvailable()) return;
    try {
      libWrapper.unregister(MODULE_ID, target);
      this.#registeredWrappers.delete(target);
      LogUtil.log(`LibWrapperUtil.unregister - Successfully unregistered: ${target}`);
    } catch (error) {
      LogUtil.error(`LibWrapperUtil.unregister - Failed to unregister ${target}:`, [error]);
    }
  }

  /**
   * Unregister every wrapper this module registered
   */
  static unregisterAll() {
    if (!this.isAvailable()) return;
    for (const target of this.#registeredWrappers) {
      this.unregister(target);
    }
    this.#registeredWrappers.clear();
    LogUtil.log("LibWrapperUtil.unregisterAll - All wrappers unregistered");
  }

  /**
   * Targets currently wrapped by this module
   * @returns {string[]}
   */
  static getRegisteredWrappers() {
    return Array.from(this.#registeredWrappers);
  }

  /**
   * Show the libWrapper recommendation once to GMs. When libWrapper is present the
   * "shown" flag is reset so the notice reappears if the module is later removed.
   */
  static showMissingLibWrapperNotification() {
    if (!game.user.isGM) return;
    const tag = getSettings().libWrapperNotificationShown.tag;
    const alreadyShown = SettingsUtil.get(tag);
    if (this.isAvailable()) {
      if (alreadyShown) {
        SettingsUtil.set(tag, false);
      }
      return;
    }
    if (alreadyShown) return;
    NotifyUtil.info(
      game.i18n.localize(`${LANG_PREFIX}.notifications.libWrapperRecommended`),
      { permanent: true, console: false }
    );
    SettingsUtil.set(tag, true);
  }
}
