import { getSettings } from "../constants/Settings.mjs";
import { SettingsUtil } from "../utils/SettingsUtil.mjs";
import { ActorResolver } from "../actors/ActorResolver.mjs";

/**
 * Hover preview for token bar entries: highlights the canvas token and, for the GM,
 * temporarily shows what the token sees.
 * @module tokens/TokenVisionPreview
 */
export class TokenVisionPreview {
  /** @type {Set<Token>} */
  static #hoveredTokens = new Set();
  static #previewControlToken = null;
  /** @type {Token[]} */
  static #previouslyControlled = [];

  /**
   * Whether the hover preview setting is on
   * @returns {boolean}
   */
  static isEnabled() {
    return !!SettingsUtil.get(getSettings().showTokenVisionOnHover.tag);
  }

  /**
   * Canvas token for a unique id
   * @param {string} uniqueId
   * @returns {Token|null}
   */
  static #tokenFor(uniqueId) {
    const participant = ActorResolver.resolveParticipant(uniqueId);
    if (!participant) return null;
    return ActorResolver.getCanvasToken(participant) ?? ActorResolver.getCanvasToken({ actorId: participant.actorId });
  }

  /**
   * Highlight the token, and for the GM preview its vision when the setting is on
   * @param {string} uniqueId
   */
  static show(uniqueId) {
    const token = this.#tokenFor(uniqueId);
    if (!token || token.hover) return;

    token.hover = true;
    token.renderFlags.set({ refreshState: true });
    this.#hoveredTokens.add(token);

    if (!this.isEnabled() || !game.user.isGM || !canvas.scene?.tokenVision || !token.document.sight?.enabled) return;
    this.#previouslyControlled = [...canvas.tokens.controlled];
    this.#previewControlToken = token;
    Object.defineProperty(token, "controlled", { get: () => true, configurable: true });
    token.initializeVisionSource();
    canvas.perception.update({ initializeVision: true, refreshVision: true });
  }

  /**
   * Remove the highlight and restore the previous vision state
   * @param {string} uniqueId
   */
  static hide(uniqueId) {
    const token = this.#tokenFor(uniqueId);
    if (!token || !this.#hoveredTokens.has(token)) return;

    token.hover = false;
    token.renderFlags.set({ refreshState: true });
    this.#hoveredTokens.delete(token);

    if (this.#previewControlToken !== token || !game.user.isGM) return;
    delete token.controlled;
    token.initializeVisionSource();
    for (const controlled of this.#previouslyControlled) {
      if (controlled.scene === canvas.scene) controlled.initializeVisionSource();
    }
    canvas.perception.update({ initializeVision: true, refreshVision: true });
    this.#previewControlToken = null;
    this.#previouslyControlled = [];
  }
}
