import { AdapterRegistry } from "../core/AdapterRegistry.mjs";
import { TABS } from "../constants/General.mjs";
import { GroupSources } from "./groups/GroupSources.mjs";

/**
 * Decides which tab an actor belongs to. Ownership drives the PC / NPC split in every system;
 * the adapter's actorTypes section only decides which actor types are listed and which are groups.
 * @module actors/ActorClassifier
 */
export class ActorClassifier {
  /**
   * Whether a non-GM user owns the actor, through their own entry or the "All Players" default level
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isPlayerOwned(actor) {
    if (!actor) return false;
    return game.users.some(user => !user.isGM && actor.testUserPermission(user, "OWNER"));
  }

  /**
   * Whether the actor is a non-GM user's assigned character
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isAssignedCharacter(actor) {
    if (!actor?.id) return false;
    return game.users.some(user => !user.isGM && user.character?.id === actor.id);
  }

  /**
   * Whether the actor type is a group, declared by the adapter or detected in the system
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isGroupActor(actor) {
    return GroupSources.isGroupActor(actor);
  }

  /**
   * Whether the actor type should appear in the bar at all
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isListed(actor) {
    if (!actor) return false;
    if (this.isGroupActor(actor)) return true;
    const listed = AdapterRegistry.active.actorTypes?.listed;
    if (!listed) return true;
    return listed.includes(actor.type);
  }

  /**
   * Tab for an actor
   * @param {Actor} actor
   * @returns {string} One of TABS
   */
  static classify(actor) {
    if (this.isGroupActor(actor)) return TABS.GROUP;
    return this.isPlayerOwned(actor) || this.isAssignedCharacter(actor) ? TABS.PC : TABS.NPC;
  }
}
