import { LANG_PREFIX } from "../../constants/General.mjs";
import { LogUtil } from "../../utils/LogUtil.mjs";
import { ActorResolver } from "../ActorResolver.mjs";
import { ActorStatusFlags } from "../ActorStatusFlags.mjs";
import { SavedGroups } from "../groups/SavedGroups.mjs";
import { GroupMembership } from "../groups/GroupMembership.mjs";
import { NotifyUtil } from "../../utils/NotifyUtil.mjs";

/**
 * Drag-to-remove for the token bar: dragging an actor row outside the menu blocks the actor, dragging a group
 * member outside removes it from that group, and dragging a saved group row outside deletes the group.
 * Listener references are kept per menu instance so repeated renders replace instead of stack them.
 * @module actors/drag/ActorDragUtil
 */
export class ActorDragUtil {
  /** @type {WeakMap<Object, {listeners: Object|null, currentDrag: Object|null}>} */
  static #state = new WeakMap();

  /**
   * Drag bookkeeping for a menu instance
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   * @returns {{listeners: Object|null, currentDrag: Object|null}}
   */
  static #stateFor(menu) {
    let state = this.#state.get(menu);
    if (!state) {
      state = { listeners: null, currentDrag: null };
      this.#state.set(menu, state);
    }
    return state;
  }

  /**
   * Attach drag listeners to every draggable actor row and the document
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static initializeActorDrag(menu) {
    this.removeDragListeners(menu);
    const actorElements = menu.element.querySelectorAll('.actor-list .actor.drag-wrapper[draggable="true"]');
    actorElements.forEach(actorElement => {
      actorElement.addEventListener("dragstart", event => this.handleDragStart(event, menu));
      actorElement.addEventListener("dragend", event => this.handleDragEnd(event, menu));
    });
    const listeners = {
      menuDragOver: event => this.handleDragOver(event),
      menuDrop: event => this.handleDrop(event, menu),
      globalDragOver: event => this.handleGlobalDragOver(event, menu),
      globalDrop: event => this.handleGlobalDrop(event, menu)
    };
    menu.element.addEventListener("dragover", listeners.menuDragOver);
    menu.element.addEventListener("drop", listeners.menuDrop);
    document.addEventListener("dragover", listeners.globalDragOver);
    document.addEventListener("drop", listeners.globalDrop);
    this.#stateFor(menu).listeners = listeners;
  }

  /**
   * Store drag data and show a translucent placeholder as the drag image. A group row that declares
   * a source (`data-source`) is handled as a group; any other row, including a host's system group
   * actor rendered without a source, is an actor that can be dragged out to block it.
   * @param {DragEvent} event
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static handleDragStart(event, menu) {
    const actorElement = event.currentTarget;
    if (actorElement.classList.contains("actor-group") && actorElement.dataset.source) {
      this.#handleGroupDragStart(event, actorElement, menu);
      return;
    }
    const actorId = actorElement.dataset.actorId;
    const actor = ActorResolver.getActor(actorId);
    if (!actor) {
      event.preventDefault();
      return;
    }
    LogUtil.log("ActorDragUtil.handleDragStart", [actor.name, actorId]);
    event.dataTransfer.setData("text/plain", actorId);
    const memberOf = game.user.isGM ? GroupMembership.memberRefFrom(actorElement) : null;
    event.dataTransfer.setData("application/json", JSON.stringify({
      actorId,
      actorName: actor.name,
      uniqueId: actorElement.dataset.id,
      tokenId: actorElement.dataset.tokenId || null,
      memberOf
    }));
    event.dataTransfer.effectAllowed = "move";
    actorElement.classList.add("dragging");
    const rect = actorElement.getBoundingClientRect();
    const dragImage = this.#createPlaceholderDragImage(rect);
    if (dragImage) {
      event.dataTransfer.setDragImage(dragImage, rect.width / 2, rect.height / 2);
      setTimeout(() => dragImage.remove(), 0);
    }
    this.#stateFor(menu).currentDrag = {
      actorId,
      uniqueId: actorElement.dataset.id,
      actorElement,
      startTime: Date.now()
    };
  }

  /**
   * Store the drag data of a saved group row, which is removed when dropped outside the menu
   * @param {DragEvent} event
   * @param {HTMLElement} groupElement
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static #handleGroupDragStart(event, groupElement, menu) {
    const groupId = groupElement.dataset.id;
    const groupName = groupElement.querySelector(".actor-name")?.textContent ?? "";
    if (groupElement.dataset.source !== "saved") {
      event.preventDefault();
      return;
    }
    LogUtil.log("ActorDragUtil.#handleGroupDragStart", [groupName, groupId]);
    event.dataTransfer.setData("text/plain", groupId);
    event.dataTransfer.setData("application/json", JSON.stringify({ groupId, groupName }));
    event.dataTransfer.effectAllowed = "move";
    groupElement.classList.add("dragging");
    const rect = groupElement.getBoundingClientRect();
    const dragImage = this.#createPlaceholderDragImage(rect);
    if (dragImage) {
      event.dataTransfer.setDragImage(dragImage, rect.width / 2, rect.height / 2);
      setTimeout(() => dragImage.remove(), 0);
    }
    this.#stateFor(menu).currentDrag = {
      groupId,
      uniqueId: groupId,
      actorElement: groupElement,
      startTime: Date.now()
    };
  }

  /**
   * Build the dashed placeholder used as drag image, attached under #interface
   * @param {DOMRect} rect - Bounds of the dragged row
   * @returns {HTMLElement|null}
   */
  static #createPlaceholderDragImage(rect) {
    const host = document.querySelector("#interface");
    if (!host) return null;
    const dragImage = document.createElement("div");
    Object.assign(dragImage.style, {
      width: `${rect.width}px`,
      height: `${rect.height}px`,
      backgroundColor: "rgba(0, 0, 0, 0.1)",
      border: "2px dashed rgba(255, 255, 255, 0.3)",
      borderRadius: "4px",
      opacity: "0.6",
      position: "absolute",
      top: "-1000px",
      left: "-1000px",
      pointerEvents: "none"
    });
    host.appendChild(dragImage);
    return dragImage;
  }

  /**
   * Drag image for group actors showing the member portraits and the group name
   * @param {HTMLElement} actorElement
   * @param {Actor} actor
   * @returns {HTMLElement}
   */
  static createGroupDragImage(actorElement, actor) {
    const source = getComputedStyle(actorElement);
    const dragImage = document.createElement("div");
    dragImage.className = "actor actor-group drag-wrapper";
    Object.assign(dragImage.style, {
      background: source.background,
      border: source.border,
      borderRadius: source.borderRadius,
      padding: source.padding
    });
    const actorImgContainer = actorElement.querySelector(".actor-img");
    if (actorImgContainer) {
      dragImage.appendChild(actorImgContainer.cloneNode(true));
    }
    const nameSource = getComputedStyle(actorElement.querySelector(".actor-name") || actorElement);
    const nameDiv = document.createElement("div");
    nameDiv.className = "actor-name";
    nameDiv.textContent = actor.name;
    Object.assign(nameDiv.style, {
      color: nameSource.color,
      fontSize: nameSource.fontSize,
      fontWeight: "bold",
      textAlign: "center",
      marginTop: "4px"
    });
    dragImage.appendChild(nameDiv);
    return dragImage;
  }

  /**
   * Drag image for regular actors: portrait and name side by side
   * @param {HTMLElement} actorElement
   * @returns {HTMLElement}
   */
  static createStandardDragImage(actorElement) {
    const source = getComputedStyle(actorElement);
    const dragImage = document.createElement("div");
    dragImage.className = actorElement.className;
    Object.assign(dragImage.style, {
      background: source.background,
      border: source.border,
      borderRadius: source.borderRadius,
      padding: source.padding,
      display: "flex",
      alignItems: "center",
      gap: "8px"
    });
    const actorImg = actorElement.querySelector(".actor-img");
    if (actorImg) {
      dragImage.appendChild(actorImg.cloneNode(true));
    }
    const actorName = actorElement.querySelector(".actor-name");
    if (actorName) {
      dragImage.appendChild(actorName.cloneNode(true));
    }
    return dragImage;
  }

  /**
   * Dragging over the menu itself never drops
   * @param {DragEvent} event
   */
  static handleDragOver(event) {
    event.preventDefault();
    event.dataTransfer.dropEffect = "none";
  }

  /**
   * A drop inside the menu cancels the removal
   * @param {DragEvent} event
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static handleDrop(event, menu) {
    event.preventDefault();
    LogUtil.log("ActorDragUtil.handleDrop - dropped within menu, canceling remove");
    this.cleanupDrag(menu);
  }

  /**
   * Whether the pointer is over the menu element
   * @param {DragEvent} event
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   * @returns {boolean}
   */
  static #isOverMenu(event, menu) {
    const menuElement = menu.element;
    const target = document.elementFromPoint(event.clientX, event.clientY);
    return !!menuElement && (menuElement === target || menuElement.contains(target));
  }

  /**
   * Highlight the dragged row as removable while outside the menu
   * @param {DragEvent} event
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static handleGlobalDragOver(event, menu) {
    const currentDrag = this.#stateFor(menu).currentDrag;
    if (!currentDrag) return;
    const actorElement = currentDrag.actorElement;
    if (!this.#isOverMenu(event, menu)) {
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      actorElement?.classList.add("drag-remove-zone");
    } else {
      event.dataTransfer.dropEffect = "none";
      actorElement?.classList.remove("drag-remove-zone");
    }
  }

  /**
   * Dropping outside the menu removes a group member from its group, deletes a saved group, or blocks the actor
   * @param {DragEvent} event
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static handleGlobalDrop(event, menu) {
    if (!this.#stateFor(menu).currentDrag) return;
    if (!this.#isOverMenu(event, menu)) {
      event.preventDefault();
      const dragData = JSON.parse(event.dataTransfer.getData("application/json"));
      if (dragData.groupId) {
        LogUtil.log("ActorDragUtil.handleGlobalDrop - deleting group", [dragData.groupName]);
        this.deleteSavedGroup(dragData.groupId, dragData.groupName);
      } else if (dragData.memberOf) {
        LogUtil.log("ActorDragUtil.handleGlobalDrop - removing group member", [dragData.memberOf]);
        GroupMembership.remove(dragData.memberOf).then(removed => removed && menu.render());
      } else {
        LogUtil.log("ActorDragUtil.handleGlobalDrop - blocking actor", [dragData.actorName]);
        this.blockActor(dragData.actorId, menu);
      }
    }
    this.cleanupDrag(menu);
  }

  /**
   * Delete a saved group after confirmation. Deleting a group cannot be undone, unlike blocking
   * an actor, so the drop asks before removing it.
   * @param {string} groupId
   * @param {string} groupName
   */
  static async deleteSavedGroup(groupId, groupName) {
    const confirmed = await foundry.applications.api.DialogV2.confirm({
      window: { title: game.i18n.localize(`${LANG_PREFIX}.ui.groups.deleteTitle`) },
      content: `<p>${game.i18n.format(`${LANG_PREFIX}.ui.groups.deleteConfirm`, { name: groupName })}</p>`,
      rejectClose: false
    });
    if (confirmed) await SavedGroups.remove(groupId);
  }

  /**
   * Clear drag state shortly after the drag ends
   * @param {DragEvent} event
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static handleDragEnd(event, menu) {
    LogUtil.log("ActorDragUtil.handleDragEnd");
    setTimeout(() => this.cleanupDrag(menu), 100);
  }

  /**
   * Block an actor and drop it from the selection
   * @param {string} actorId
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static async blockActor(actorId, menu) {
    try {
      const uniqueId = this.#stateFor(menu).currentDrag?.uniqueId
        ?? menu.element.querySelector(`[data-actor-id="${actorId}"]`)?.dataset.id;
      await ActorStatusFlags.blockActor(actorId);
      if (uniqueId) {
        menu.selectedActors.delete(uniqueId);
      }
    } catch (error) {
      LogUtil.error("ActorDragUtil.blockActor", [error]);
      NotifyUtil.error(`Failed to block actor: ${error.message}`);
    }
  }

  /**
   * Remove drag classes and forget the current drag
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static cleanupDrag(menu) {
    const state = this.#stateFor(menu);
    state.currentDrag?.actorElement?.classList.remove("dragging", "drag-remove-zone");
    state.currentDrag = null;
  }

  /**
   * Detach the menu and document listeners added by initializeActorDrag
   * @param {import("../../ui/token-bar/TokenBarApp.mjs").TokenBarApp} menu
   */
  static removeDragListeners(menu) {
    const state = this.#stateFor(menu);
    const listeners = state.listeners;
    if (!listeners) return;
    menu.element?.removeEventListener("dragover", listeners.menuDragOver);
    menu.element?.removeEventListener("drop", listeners.menuDrop);
    document.removeEventListener("dragover", listeners.globalDragOver);
    document.removeEventListener("drop", listeners.globalDrop);
    state.listeners = null;
  }
}
