import { getSettings } from "../../constants/Settings.mjs";
import { SettingsUtil } from "../../utils/SettingsUtil.mjs";

/**
 * @typedef {Object} ConfiguredRollType
 * @property {string} id - Stable id, used as the roll type identifier
 * @property {boolean} enabled - Shown in the Rolls tab
 * @property {string} label - Display label
 * @property {string} method - Function to call: "actor:<name>", "system:<name>", "sheet:<name>", "item:<name>" or
 *   "api:<path from globalThis>"; "" when the roll only uses a formula
 * @property {string} group - Option source: a value group path in actor.system ("skills"), "@items:<item type>",
 *   "@sheet-rolls", or "" for a roll without options
 * @property {Array<{key: string, label?: string}>} [options] - Fixed option list, used instead of reading the group
 * @property {{from: string, group?: string}} [secondKey] - Two-key rolls: path inside the chosen entry holding the
 *   second key (e.g. "attribute"), and the group to read its value from
 * @property {string} formula - Optional formula; when set it is rolled instead of the method. Placeholders as in args
 * @property {Array} [args] - Explicit argument template; placeholders such as "{key}" and "{fastForward}" are filled
 *   (see RollCallBuilder.fill). Without it, arguments are matched to the function's parameter names
 * @property {{from?: "roll"|"return", total?: string, passed?: string, compare?: "atLeast"|"atMost", successCount?: boolean}} [result] -
 *   Where the result is read: the Roll (default) or the function's return value; paths of the total and of a
 *   pass/fail flag; how the total compares with a target; whether the total counts successes
 * @property {string} [afterRoll] - Path of a function on the returned value to call after the roll
 */

/**
 * @typedef {Object} SystemConfig
 * @property {ConfiguredRollType[]} rollTypes
 */

/**
 * Reads and writes the GM-made configuration of the running system, stored per system id in a world setting
 * @module adapters/configured/SystemConfigStore
 */
export class SystemConfigStore {
  /**
   * Configuration of the running system, or null when the GM has not configured it
   * @returns {SystemConfig|null}
   */
  static get() {
    const all = SettingsUtil.get(getSettings().systemConfigs.tag) ?? {};
    const config = all[game.system?.id];
    return config && Array.isArray(config.rollTypes) ? config : null;
  }

  /**
   * Save the configuration of the running system
   * @param {SystemConfig} config
   * @returns {Promise<void>}
   */
  static async set(config) {
    const tag = getSettings().systemConfigs.tag;
    const all = foundry.utils.deepClone(SettingsUtil.get(tag) ?? {});
    all[game.system.id] = config;
    await SettingsUtil.set(tag, all);
  }

  /**
   * Remove the configuration of the running system
   * @returns {Promise<void>}
   */
  static async clear() {
    const tag = getSettings().systemConfigs.tag;
    const all = foundry.utils.deepClone(SettingsUtil.get(tag) ?? {});
    delete all[game.system.id];
    await SettingsUtil.set(tag, all);
  }
}
