import { AdapterRegistry } from "../../core/AdapterRegistry.mjs";
import { GenericGroups } from "../../adapters/generic/GenericGroups.mjs";
import { getSettings } from "../../constants/Settings.mjs";
import { LANG_PREFIX } from "../../constants/General.mjs";
import { SettingsUtil } from "../../utils/SettingsUtil.mjs";

/**
 * Id of the module's own saved groups among the group sources
 * @type {string}
 */
export const SAVED_GROUP_SOURCE = "saved";

/**
 * Decides which kinds of group feed the Groups tab: the module's saved groups and every actor type
 * that holds members, whether the adapter declares it or GenericGroups detects it from the system.
 * The setting stores the sources the GM turned off, so newly detected types start enabled.
 * @module actors/groups/GroupSources
 */
export class GroupSources {
  /**
   * Whether the actor is a group, by the adapter's rules or by detection. Independent of the setting,
   * so a turned-off group type stays out of the PC and NPC tabs.
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isGroupActor(actor) {
    if (!actor) return false;
    const adapter = AdapterRegistry.active;
    if (adapter.groups?.isGroupActor?.(actor)) return true;
    if ((adapter.actorTypes?.group ?? []).includes(actor.type)) return true;
    return GenericGroups.isGroupActor(actor);
  }

  /**
   * Group actors of every enabled type
   * @returns {Actor[]}
   */
  static getGroupActors() {
    return game.actors.filter(actor => this.isGroupActor(actor) && this.isEnabled(actor.type));
  }

  /**
   * Members of a group actor, read by the adapter when it owns the type, otherwise by detection
   * @param {Actor} groupActor
   * @returns {Promise<Array<{actor: Actor, quantity: number}>>}
   */
  static async getGroupMembers(groupActor) {
    const adapterGroups = AdapterRegistry.active.groups;
    if (adapterGroups?.getGroupMembers && adapterGroups.isGroupActor?.(groupActor)) {
      return adapterGroups.getGroupMembers(groupActor);
    }
    return GenericGroups.getGroupMembers(groupActor);
  }

  /**
   * What the Create group action makes: a saved group when those are on, which takes priority,
   * otherwise an actor of the first enabled system group type
   * @returns {string|null} SAVED_GROUP_SOURCE, an actor type, or null when every source is off
   */
  static creationTarget() {
    if (this.isEnabled(SAVED_GROUP_SOURCE)) return SAVED_GROUP_SOURCE;
    return this.systemTypes().find(type => this.isEnabled(type)) ?? null;
  }

  /**
   * Create a group actor of a system type holding the given actors. The adapter's createGroup is used
   * when it provides one, otherwise the members are written to the field detected in the type's schema.
   * @param {string} type - Actor type
   * @param {string} name
   * @param {Actor[]} actors - World actors to add as members
   * @returns {Promise<Actor|null>}
   */
  static async createGroupActor(type, name, actors) {
    const adapterGroups = AdapterRegistry.active.groups;
    if (typeof adapterGroups?.createGroup === "function") {
      const created = await adapterGroups.createGroup(type, name, actors);
      if (created !== undefined) return created ?? null;
    }
    const data = foundry.utils.mergeObject({ name, type }, GenericGroups.memberData(type, actors));
    return (await Actor.implementation.create(data)) ?? null;
  }

  /**
   * Actor types of the system that hold members, found from the declared actor types so a type
   * is listed even before any actor of it exists in the world
   * @returns {string[]}
   */
  static systemTypes() {
    const adapter = AdapterRegistry.active;
    const types = new Set(adapter.actorTypes?.group ?? []);
    if (adapter.groups?.isGroupActor) {
      for (const type of GenericGroups.actorTypes()) {
        if (this.#adapterTreatsTypeAsGroup(adapter, type)) types.add(type);
      }
    }
    for (const type of GenericGroups.detectedTypes()) types.add(type);
    return Array.from(types);
  }

  /**
   * Whether the adapter's isGroupActor accepts an actor of the type, tested with a stand-in carrying only the type
   * @param {import("../../adapters/SystemAdapter.mjs").SystemAdapter} adapter
   * @param {string} type
   * @returns {boolean}
   */
  static #adapterTreatsTypeAsGroup(adapter, type) {
    try {
      return !!adapter.groups.isGroupActor({ type, system: {} });
    } catch (error) {
      return false;
    }
  }

  /**
   * Every selectable source: saved groups first, then the system's group actor types
   * @returns {string[]}
   */
  static available() {
    return [SAVED_GROUP_SOURCE, ...this.systemTypes()];
  }

  /**
   * Whether a source is turned on
   * @param {string} sourceId - SAVED_GROUP_SOURCE or an actor type
   * @returns {boolean}
   */
  static isEnabled(sourceId) {
    return !this.#disabled().includes(sourceId);
  }

  /**
   * Whether at least one system group type is turned on
   * @returns {boolean}
   */
  static hasEnabledSystemGroups() {
    return this.systemTypes().some(type => this.isEnabled(type));
  }

  /**
   * Options for the settings multi-select
   * @returns {Array<{value: string, label: string, selected: boolean}>}
   */
  static options() {
    return this.available().map(value => ({ value, label: this.#label(value), selected: this.isEnabled(value) }));
  }

  /**
   * Stored setting value for a selection made in the settings form
   * @param {string[]|string|null} selected - Sources the GM kept on
   * @returns {string[]} Sources to store as turned off
   */
  static disabledFromSelection(selected) {
    const kept = new Set([selected ?? []].flat().filter(Boolean));
    return this.available().filter(id => !kept.has(id));
  }

  /**
   * Sources stored as turned off
   * @returns {string[]}
   */
  static #disabled() {
    const value = SettingsUtil.get(getSettings().groupSourcesDisabled.tag);
    return Array.isArray(value) ? value : [];
  }

  /**
   * Display label of a source
   * @param {string} sourceId
   * @returns {string}
   */
  static #label(sourceId) {
    if (sourceId === SAVED_GROUP_SOURCE) return game.i18n.localize(`${LANG_PREFIX}.ui.groups.savedGroupsSource`);
    const labelKey = CONFIG.Actor?.typeLabels?.[sourceId];
    const label = labelKey ? game.i18n.localize(labelKey) : sourceId;
    return game.i18n.format(`${LANG_PREFIX}.ui.groups.actorTypeSource`, { type: label });
  }
}
