import { MODULE_ID, LANG_PREFIX } from "../constants/General.mjs";
import { HOOKS_CORE } from "../constants/Hooks.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";
import { ActorStatusFlags } from "./ActorStatusFlags.mjs";

const ICON_SELECTOR = "span.fas.fa-bolt, span.fas.fa-bolt-slash";

/**
 * Shows a bolt icon next to favourite actors and a slashed bolt next to blocked actors in the
 * Actor Directory. Clicking the icon clears the corresponding flag.
 * @module actors/ActorDirectoryIcons
 */
export class ActorDirectoryIcons {
  /**
   * Register directory hooks and decorate an already rendered directory
   */
  static initialize() {
    LogUtil.log("ActorDirectoryIcons.initialize");
    Hooks.on(HOOKS_CORE.RENDER_ACTOR_DIRECTORY, (app, html) => this.#onRenderActorDirectory(app, html));
    Hooks.on(HOOKS_CORE.UPDATE_ACTOR, (actor, changes) => this.#onUpdateActor(actor, changes));
    this.#updateExistingDirectory();
  }

  /**
   * Decorate the directory if it is already on screen
   */
  static #updateExistingDirectory() {
    const actorDirectory = ui.actors;
    if (actorDirectory?.rendered && actorDirectory.element) {
      this.#onRenderActorDirectory(actorDirectory, actorDirectory.element);
    }
  }

  /**
   * Decorate every actor entry of a rendered directory
   * @param {Application} app
   * @param {HTMLElement|Object} html - HTMLElement in v13+, jQuery in older cores
   */
  static #onRenderActorDirectory(app, html) {
    const root = html?.[0] ?? html;
    if (!root?.querySelectorAll) return;
    this.#decorateEntries(root.querySelectorAll(".directory-item.actor"));
  }

  /**
   * Refresh the icon when one of this module's flags changes
   * @param {Actor} actor
   * @param {Object} changes
   */
  static #onUpdateActor(actor, changes) {
    const flagChanges = changes.flags?.[MODULE_ID];
    if (!flagChanges) return;
    LogUtil.log("ActorDirectoryIcons - flags changed", [actor.name, flagChanges]);
    this.refreshActorIcon(actor.id);
  }

  /**
   * Update the icon of each directory entry
   * @param {Iterable<HTMLElement>} elements
   */
  static #decorateEntries(elements) {
    elements.forEach(element => {
      const actorId = element.dataset.entryId || element.dataset.documentId;
      if (actorId) {
        this.#updateActorIcon(element, actorId);
      }
    });
  }

  /**
   * Replace the icon of one directory entry according to the actor's flags
   * @param {HTMLElement} actorElement
   * @param {string} actorId
   */
  static #updateActorIcon(actorElement, actorId) {
    actorElement.querySelector(ICON_SELECTOR)?.remove();
    const actor = game.actors.get(actorId);
    if (!actor) return;
    const { isFavorite, isBlocked } = ActorStatusFlags.getActorStatus(actor);
    if (!isFavorite && !isBlocked) return;
    const icon = document.createElement("span");
    icon.className = isBlocked ? "fas fa-bolt-slash" : "fas fa-bolt";
    icon.dataset.tooltip = game.i18n.localize(`${LANG_PREFIX}.contextMenu.${isBlocked ? "unblockFromMenu" : "removeFavorite"}`);
    icon.dataset.tooltipDirection = "LEFT";
    icon.style.cursor = "pointer";
    icon.addEventListener("click", event => {
      event.preventDefault();
      event.stopPropagation();
      if (isBlocked) {
        ActorStatusFlags.toggleBlocked(actorId, false);
      } else {
        ActorStatusFlags.toggleFavorite(actorId, false);
      }
    });
    actorElement.appendChild(icon);
  }

  /**
   * Refresh the icon of a single actor
   * @param {string} actorId
   */
  static refreshActorIcon(actorId) {
    const actorElement = document.querySelector(
      `.directory-item.actor[data-entry-id="${actorId}"], .directory-item.actor[data-document-id="${actorId}"]`
    );
    if (actorElement) {
      this.#updateActorIcon(actorElement, actorId);
    }
  }

  /**
   * Refresh the icons of every actor entry currently in the DOM
   */
  static refreshAllIcons() {
    LogUtil.log("ActorDirectoryIcons.refreshAllIcons");
    this.#decorateEntries(document.querySelectorAll(".directory-item.actor"));
  }
}
